package com.huiqiyikang.assessment.mapper; import com.huiqiyikang.assessment.entity.AssessmentTask; import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper; import java.util.*; public interface AssessmentTaskRepository extends BaseMapperX<AssessmentTask>{
 default List<AssessmentTask> findVisibleByClassIds(Collection<Long> ids){return ids==null||ids.isEmpty()?List.of():selectList(new QueryWrapper<AssessmentTask>().in("class_id",ids).ne("status","deleted").orderByDesc("created_at").orderByDesc("id"));}
default List<AssessmentTask> findByClassIdAndStatus(Long id,String status){return selectList(new QueryWrapper<AssessmentTask>().eq("class_id",id).eq("status",status));}}
